// TH18 v1.00a Extra / st07bs.ecl::BossCard1 (938-1003) + BossCard1_at (1329-1353)
// Source spell ID 87.  Isolated control shell from transcribe/th18/validation.md.
// Source frame 0 = real enemy task start; source timerReset(951) = source frame 4.

const TIME_LIMIT: int = 4380;     // 120 opening buffer + 4200 source active timer + 60 tail
const OPENING_BUFFER: int = 120;
const TIMEOUT_TICKS: int = 4200;  // source setInterrupt(0, 0, 4200, "Boss2") from timerReset

// Source.txt 1338-1342:
//   ANIM a=1 (birth retreat only) / OFFSCREEN a=480,b=0 / three sequential ANGLE_ACCEL
//   (a,r,s) = (80,0.03,1deg), (100,-0.021,1deg), (150,0.028,-2deg)
// The card at(1) call mirrors the two 1deg terms and the -2deg term.
// OFFSCREEN: three finite effects end while it is active => each reruns the active
// handler once; target keeps one decrement per frame, so 480-3 = 477.
xformdef BOSS_CARD1_AT(s1: angle, r1: fx, s2: angle, r2: fx, s3: angle, r3: fx) {
    offscreen_keep(477);
    set_ang_vel(s1);
    set_accel(r1);
    @80 add_speed(0fx);
    set_ang_vel(s2);
    set_accel(r2);
    @100 add_speed(0fx);
    set_ang_vel(s3);
    set_accel(r3);
    @150 add_speed(0fx);
    set_ang_vel(0deg);
    set_accel(0fx);
}

// Source moveRand(60,4,1.0) + moveLimit(0,128,240,224) sample from movement.md,
// with this card's limit box (x[-120,120], y[16,240]) and inner selection box
// (x+-60, y72..184 = centre +- width/height/4).
sub card_arm_next_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = (60 - k) as fx / 60; }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -120fx { nx = -120fx; }
    if nx > 120fx { nx = 120fx; }
    if ny < 16fx { ny = 16fx; }
    if ny > 240fx { ny = 240fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub card_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card_arm_next_step();
}

// moveRand direction selection, strict branches and y fabs before the +-pi/2 guard.
sub card_move_rand() {
    var r: int = rand(65536) - 32768;   // signed full-circle BAM, source signed float*pi
    var a: int = r / 3;
    if $self_x < -60fx {
        a = r / 3;
    } else if $self_x > 60fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }  // source normalizes only this branch
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
        // no normalization here: source fabs tests run before any wrap
    }
    if $self_y < 72fx {
        if a < 0 { a = -a; }
    } else if $self_y > 184fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a as angle);
}

// Every source wait in the attack uses this helper so the next source movement tick
// is armed before phase 5.  Stops at the 4200-frame source timeout.
sub card_wait(frames: int) {
    for i in 0..frames {
        if self_int(1) >= TIMEOUT_TICKS { return; }
        wait(1);
        card_arm_next_step();
        set_self_int(1, self_int(1) + 1);
    }
}

// Source BossCard1_at(1329-1353): etNew/etAim(3)/etSprite(12,6)/etCount(B,1)/
// etAngle(RANDRAD,9deg)/etSpeed(0.3,0.2)/etEx below, then 15 volleys 3 frames apart.
sub boss_card1_at(id: int, n: int, s1: angle, r1: fx, s2: angle, r2: fx, s3: angle, r3: fx) {
    sh_reset(id);
    sh_sprite(id, TH18_ARROWHEAD, 6);   // source etSprite(type=12, color=6)
    sh_ring(id, 1);                     // source etAim(3): fixed-direction full ring
    sh_aim(id, 0);
    sh_count(id, n, 1);                 // source etCount($B, 1)
    sh_speed(id, 0.3fx, 0fx);           // source etSpeed(0.3,0.2), M=1 uses 0.3
    sh_dist(id, -1.2fx);                // source ANIM a=1: position -= 4*velocity
    sh_xform(id, BOSS_CARD1_AT(s1, r1, s2, r2, s3, r3));
    var alpha: angle = (rand(65536) - 32768) as angle;  // source %I = %RANDRAD, once per call
    sh_angle(id, alpha, 9deg);          // source etAngle(%I, 0.15707964f), M=1 layer offset
    for v in 0..15 {
        sh_fire(id);
        card_wait(3);
        if self_int(1) >= TIMEOUT_TICKS { return; }
    }
}

async sub source_enemy() {
    // Public entry Boss(): setHurtbox(40,40), setHitbox(48,48); circular branch uses 0.5.
    set_invuln(65535);
    set_hitbox(24fx);
    set_hurtbox(20fx);
    set_self_int(0, 0);   // moveRand step counter
    set_self_int(1, 0);   // source timer ticks after timerReset
    set_self_fx(0, 0fx);  // logical direction cos
    set_self_fx(1, 0fx);  // logical direction sin

    // Source 947-960: 4-frame prelude (setChapter/unknown569/timerReset/funcSet/etc.);
    // segment/timer declaration is handled by the control phase shell.
    wait(4);
    set_self_int(1, 0);

    // Source 973-975: movePosTime(60,4,0,128) from entry position (0,128),
    // then time label +90 (source time 94).
    move_to(60, 0fx, 128fx, EASE_QUAD_OUT);
    wait(60);
    set_self_int(1, 60);
    wait(30);
    set_self_int(1, 90);

    // Source 977-981: anm316 is presentation; $A=120 and %F0=1 are never read here.
    var b: int = 20;      // $B
    var e: int = 10000;   // $E
    while e > 0 {
        // Source 982: BossCard1_1076
        boss_card1_at(0, b, 1deg, 0.03fx, 1deg, -0.021fx, -2deg, 0.028fx);
        if self_int(1) >= TIMEOUT_TICKS { break; }
        card_wait(60);
        if self_int(1) >= TIMEOUT_TICKS { break; }
        card_move_rand();
        if self_int(1) >= TIMEOUT_TICKS { break; }
        card_wait(60);
        if self_int(1) >= TIMEOUT_TICKS { break; }
        // Source 987: mirrored angle terms for the second et slot
        boss_card1_at(1, b, -1deg, 0.03fx, -1deg, -0.021fx, 2deg, 0.028fx);
        if self_int(1) >= TIMEOUT_TICKS { break; }
        card_wait(60);
        if self_int(1) >= TIMEOUT_TICKS { break; }
        card_move_rand();
        if self_int(1) >= TIMEOUT_TICKS { break; }
        card_wait(60);
        if self_int(1) >= TIMEOUT_TICKS { break; }
        // Source 991-995: B += 2 up to 32; %F0=1 is an unread write.
        if b < 32 { b = b + 2; }
        e = e - 1;
    }

    // Source 998-1001: after the loop only wait; the phase shell ends the segment.
    loop { wait(1); }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 18000, 0, 0, 0, source_enemy);  // source lifeSet(18000)
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}

